import { Box, Typography, TextField, Button, Stack, Divider, List, ListItem, ListItemText } from '@mui/material';
import { useState } from 'react';

export default function PaymentScreen() {
  const [slip, setSlip] = useState(null);
  const [history, setHistory] = useState([
    { date: '2025-08-01', amount: '฿1,000', status: 'ชำระแล้ว' },
    { date: '2025-07-01', amount: '฿1,000', status: 'ชำระแล้ว' },
  ]);

  const handleSlipUpload = (e:any) => {
    // setSlip(URL.createObjectURL(e.target.files[0]));
  };

  return (
    <Box sx={{ p: 3, maxWidth: 600, mx: 'auto' }}>
      <Typography variant="h5" gutterBottom>ชำระเงิน</Typography>

      <Stack spacing={2}>
        <TextField label="จำนวนเงินที่โอน (บาท)" variant="outlined" fullWidth />
        
        <Button variant="contained" component="label">
          แนบสลิปการโอน
          <input type="file" hidden onChange={handleSlipUpload} />
        </Button>

        {slip && (
          <Box sx={{ mt: 1 }}>
            <Typography variant="body2">สลิปที่แนบ:</Typography>
            <img src={slip} alt="slip" style={{ width: '100%', borderRadius: 8 }} />
          </Box>
        )}

        <Button variant="contained" color="success">ยืนยันการชำระเงิน</Button>
      </Stack>

      <Divider sx={{ my: 4 }} />

      <Typography variant="h6">ประวัติการชำระเงิน</Typography>
      <List>
        {history.map((item, index) => (
          <ListItem key={index} sx={{ px: 0 }}>
            <ListItemText
              primary={`${item.date} - ${item.amount}`}
              secondary={item.status}
            />
          </ListItem>
        ))}
      </List>
    </Box>
  );
}
